from html.parser import HTMLParser
from pathlib import Path
import sys,re
class Links(HTMLParser):
 def __init__(self): super().__init__(); self.href=None; self.label=[]
 def handle_starttag(self,t,a):
  if t=='a': self.href=dict(a).get('href',''); self.label=[]
 def handle_data(self,s): 
  if self.href is not None: self.label.append(s)
 def handle_endtag(self,t):
  if t=='a' and self.href is not None:
   s=' '.join(' '.join(self.label).split())
   if s and re.search(r'job|locali[sz]|proof|\bQA\b',s+' '+self.href,re.I): print(s[:160],self.href.split('#')[0][:230])
   self.href=None
p=Links(); p.feed(Path(sys.argv[1]).read_text())
